 id=f'A{len(rows)+1:03}';p=OUT/'사운드'/f'{id}_보조_{cat.replace("·","_")}.ogg';u=base+'sounds/'+name;p.write_bytes(urllib.request.urlopen(u,timeout=20).read())
 info=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-show_streams','-of','json',str(p)]));s=info['streams'][0];a=np.frombuffer(subprocess.check_output(['ffmpeg','-v','error','-i',str(p),'-f','f32le','-']),dtype='<f4');peak=float(np.max(np.abs(a)));gain=-3-20*math.log10(peak);dur=float(info['format']['duration']);preview=OUT/'사운드/미리듣기'/f'{id}.mp3'
